SELECT s.item_id FROM wf_market_statistics_sync s
WHERE s.platform=#{platform} AND s.source=#{source} AND s.collection_day=#{day}
AND NOT () AND s.daily_attempts < #{maxAttempts}
ORDER BY COALESCE(s.last_attempt_at, 0), s.item_id

SELECT COUNT(*) AS total_items,
COALESCE(SUM(CASE WHEN

THEN 1 ELSE 0 END), 0) AS processed_items,
COALESCE(SUM(CASE WHEN NOT () AND s.daily_attempts < #{maxAttempts}
THEN 1 ELSE 0 END), 0) AS retryable_items,
COALESCE(SUM(CASE WHEN NOT () AND s.daily_attempts >= #{maxAttempts}
THEN 1 ELSE 0 END), 0) AS exhausted_items
FROM wf_market_statistics_sync s
WHERE s.platform=#{platform} AND s.source=#{source} AND s.collection_day=#{day}

mapper.update:
UPDATE wf_market_statistics_sync
SET last_success_at=#{now},
    last_data_day=#{day},
    consecutive_failures=0,
    last_error=NULL,
    published_success=IF(published_day = #{day}, 1, published_success)
WHERE item_id = #{itemId}
  AND platform = #{platform}
  AND source = #{source}

UPDATE wf_market_statistics_sync
SET last_attempt_at=#{now},
    daily_attempts=daily_attempts + 1
WHERE item_id = #{itemId}
  AND platform = #{platform}
  AND source = #{source}
  AND collection_day = #{day}
  AND daily_attempts < #{maxAttempts}

UPDATE wf_market_statistics_sync
SET last_attempt_at=#{now},
    consecutive_failures=consecutive_failures + 1,
    last_error=#{error}
WHERE item_id = #{itemId}
  AND platform = #{platform}
  AND source = #{source}
